// Always use named parameter for apiKey and obtain from process.env.GEMINI_API_KEY
const ai = new GoogleGenAI({ 
  apiKey: process.env.GEMINI_API_KEY || process.env.API_KEY,
  httpOptions: {
    headers: {
      'User-Agent': 'aistudio-build',
    }
  }
});

// Keep track of rate-limited models with their expiration timestamps
const rateLimitCache = new Map<string, number>();
const BYPASS_COOLDOWN_DURATION = 12 * 60 * 60 * 1000; // 12 hours for persistent/daily quota exhaustion
const RATE_LIMIT_DURATION = 30 * 1000; // 30 seconds for per-minute API rate limits
const TRANSIENT_503_COOLDOWN = 10 * 1000; // 10 seconds for 503 high-demand spikes

// Robust fallback helper for Gemini content generation to gracefully handle 429/503 errors and strip unsupported configurations
async function generateContentWithFallback(params: any): Promise<GenerateContentResponse> {
  const originalModel = params.model || "gemini-3.1-flash-lite";
  const modelsToTry = [
    originalModel,
    "gemini-3.1-flash-lite",
    "gemini-2.5-flash-lite",
    "gemini-3.7-flash",
    "gemini-flash-latest",
    "gemini-2.5-flash"
  ];

  let lastError: any;
  // Filter out duplicates preserving order
  const uniqueModels = Array.from(new Set(modelsToTry));

  const now = Date.now();
  // Filter out models that are actively in their cooldown period
  const openModels = uniqueModels.filter(m => !rateLimitCache.has(m) || now >= (rateLimitCache.get(m) || 0));
  const coolingModels = uniqueModels.filter(m => rateLimitCache.has(m) && now < (rateLimitCache.get(m) || 0));

  // Prioritize open/available models first, then fall back to cooling models
  const modelsToExecute = openModels.length > 0 ? [...openModels, ...coolingModels] : uniqueModels;

  for (const model of modelsToExecute) {
    const maxRetries = 1;
    for (let attempt = 0; attempt <= maxRetries; attempt++) {
      try {
        const callParams = { 
          ...params, 
          model,
          config: params.config ? { ...params.config } : undefined
        };
        
        // Strip thinkingConfig and thinkingBudget for standard models
        if (callParams.config) {
          delete callParams.config.thinkingConfig;
          delete callParams.config.thinkingBudget;
        }

        console.log(`[GEMINI SDK LOG] Attempting content generation with model: ${model} (Attempt ${attempt + 1}/${maxRetries + 1})`);
        const res = await ai.models.generateContent(callParams);
        // Clear any previous cooldown for this model upon success
        if (rateLimitCache.has(model)) {
          rateLimitCache.delete(model);
        }
        return res;
      } catch (err: any) {
        lastError = err;
        const rawMsg = String(err?.message || err || "");
        
        let parsed: any = null;
        let cleanHeader = rawMsg;
        try {
          parsed = JSON.parse(rawMsg);
          cleanHeader = parsed?.error?.message || parsed?.message || rawMsg;
        } catch (_) {}

        const codeVal = err?.status || err?.code || parsed?.error?.code || parsed?.code || "";
        const statusVal = parsed?.error?.status || err?.status || "";
        cleanHeader = typeof cleanHeader === "string" ? cleanHeader.split("\n")[0] : "Service exception";
        if (cleanHeader.length > 180) {
          cleanHeader = cleanHeader.substring(0, 177) + "...";
        }

        const lowerMsg = (rawMsg + " " + cleanHeader + " " + String(codeVal) + " " + String(statusVal)).toLowerCase();

        const isQuotaLimit = lowerMsg.includes("quota exceeded") || 
                             lowerMsg.includes("exceeded your current quota") || 
                             lowerMsg.includes("resource_exhausted") ||
                             lowerMsg.includes("freetier") ||
                             lowerMsg.includes("daily_limit") ||
                             lowerMsg.includes("generate_content_free_tier_requests");
                                     
        const is429 = codeVal === 429 || codeVal === "429" || lowerMsg.includes("429") || isQuotaLimit;
        
        const isTransient503 = codeVal === 503 || codeVal === "503" || statusVal === "UNAVAILABLE" ||
                                lowerMsg.includes("503") || lowerMsg.includes("unavailable") ||
                                lowerMsg.includes("high demand") || lowerMsg.includes("temporary") ||
                                lowerMsg.includes("service unavailable") || lowerMsg.includes("spikes in demand");

        if (isQuotaLimit) {
          // Hard quota exhaustion: place on cooldown and switch immediately to next model without wasting retries
          rateLimitCache.set(model, Date.now() + BYPASS_COOLDOWN_DURATION);
          console.warn(`[GEMINI QUOTA FALLBACK] Model ${model} daily/free-tier quota exhausted. Switching immediately to next fallback model.`);
          break;
        } else if (isTransient503) {
          if (attempt < maxRetries) {
            const delayMs = (attempt + 1) * 800 + Math.floor(Math.random() * 400);
            console.log(`[GEMINI 503 RETRY] Model ${model} is experiencing a transient demand spike. Retrying in ${delayMs}ms...`);
            await new Promise(resolve => setTimeout(resolve, delayMs));
            continue; // retry once with jitter
          }
          rateLimitCache.set(model, Date.now() + TRANSIENT_503_COOLDOWN);
          console.warn(`[GEMINI SEAMLESS FALLBACK] Model ${model} is experiencing high demand (503). Instantly migrating to next available fallback model.`);
          break; // move to next model immediately
        } else if (is429) {
          if (attempt < maxRetries) {
            const delayMs = Math.pow(2, attempt) * 1200 + Math.floor(Math.random() * 400);
            console.log(`[GEMINI 429 RETRY] Model ${model} is rate-limited. Retrying in ${delayMs}ms...`);
            await new Promise(resolve => setTimeout(resolve, delayMs));
            continue; // retry the same model
          }
          rateLimitCache.set(model, Date.now() + RATE_LIMIT_DURATION);
          console.warn(`[GEMINI SEAMLESS FALLBACK] Model ${model} rate-limited (${codeVal}). Placing on cooldown and trying next model.`);
          break; // move to the next fallback model
        } else {
          console.warn(`[GEMINI FALLBACK WARNING] Model ${model} failed explicitly: ${cleanHeader}. Moving to backup options.`);
          break; // break the retry loop and try another fallback model
        }
      }
    }
  }
  throw lastError;
}

