function truncateValue(value: any, maxArrayLength: number = 5, maxStringLength: number = 300, currentDepth: number = 0): any {
  if (currentDepth > 4) {
    return "... [Truncated: Deep Object]";
  }
  if (value === null || value === undefined) {
    return value;
  }
  if (typeof value === 'string') {
    if (value.length <= maxStringLength) return value;
    return value.substring(0, maxStringLength) + `... [Truncated string, original length: ${value.length}]`;
  }
  if (Array.isArray(value)) {
    if (value.length <= maxArrayLength) {
      return value.map(item => truncateValue(item, maxArrayLength, maxStringLength, currentDepth + 1));
    }
    const truncated = value.slice(0, maxArrayLength).map(item => truncateValue(item, maxArrayLength, maxStringLength, currentDepth + 1));
    return [
      ...truncated,
      `... [Truncated ${value.length - maxArrayLength} remaining elements]`
    ];
  }
  if (typeof value === 'object') {
    const result: any = {};
    const keys = Object.keys(value);
    const maxKeys = 15;
    const keysToProcess = keys.slice(0, maxKeys);
    for (const key of keysToProcess) {
      result[key] = truncateValue(value[key], maxArrayLength, maxStringLength, currentDepth + 1);
    }
    if (keys.length > maxKeys) {
      result[`_truncated_keys_info_`] = `... [Truncated ${keys.length - maxKeys} keys]`;
    }
    return result;
  }
  return value;
}

export function truncateToolResultsForTokenLimit(results: ToolResult[]): ToolResult[] {
  return results.map(res => {
    return {
      ...res,
      data: truncateValue(res.data, 5, 300, 0)
    };
  });
}

function deduplicateToolResults(results: ToolResult[]): ToolResult[] {
  if (!results || results.length <= 1) return results || [];

  const getCardFamily = (r: ToolResult): string => {
    const t = r.type;
    if (['ecc_system_status', 'ecc_connection_verification', 'ecc_autonomous_report', 'ecc_transactions', 'ecc_tcode_launcher'].includes(t)) {
      return 'ecc_system_card';
    }
    if (t.startsWith('ecc_sd_')) {
      return 'ecc_sd_card';
    }
    if (t.startsWith('hr_hcm_')) {
      return 'hr_hcm_card';
    }
    if (t.startsWith('security_') || t.startsWith('grc_')) {
      return 'security_card';
    }
    if (t.startsWith('abap_developer_') || t === 'abap_developer_autonomous_copilot') {
      return 'abap_card';
    }
    if (['fico_autonomous_copilot', 'financial_close_automation', 'accounts_payable_automation', 'accounts_receivable_automation', 'cost_controlling_automation', 'fico_autonomous_action'].includes(t)) {
      return 'fico_card';
    }
    if (['pp_autonomous_copilot', 'pp_autonomous_action'].includes(t)) {
      return 'pp_card';
    }
    if (['mm_autonomous_copilot', 'mm_autonomous_action'].includes(t)) {
      return 'mm_card';
    }
    if (['tm_autonomous_copilot', 'tm_autonomous_action', 'carrier_selection', 'load_consolidation', 'cost_intelligence', 'predictive_transportation_ai', 'autonomous_tendering', 'freight_settlement_intelligence', 'transportation_control_tower', 'autonomous_exception_management', 'multi_agent_tm_architecture', 'multi_agent_tm_action', 'tm_approval_model'].includes(t)) {
      return 'tm_card';
    }
    if (['qm_autonomous_copilot', 'qm_approval_model', 'qm_multi_agent_architecture', 'qm_qa_catalog', 'qm_autonomous_action'].includes(t)) {
      return 'qm_card';
    }
    if (t.startsWith('bw4hana_')) {
      return 'bw4hana_card';
    }
    if (t.startsWith('ewm_')) {
      return `ewm_${t}`;
    }
    if (t === 'gui_card') {
      return `gui_${r.data?.tCode || r.data?.title || 'screen'}`;
    }
    return `${t}_${r.toolName || ''}`;
  };

  const seen = new Set<string>();
  const unique: ToolResult[] = [];

  for (const r of results) {
    const family = getCardFamily(r);
    if (!seen.has(family)) {
      seen.add(family);
      unique.push(r);
    }
  }

  return unique;
}

