const PP_PRODUCTION_ROUTING_BASE = '/sap/opu/odata4/sap/ui_productionrouting/srvd/sap/ui_productionrouting/0001';

// Live Production Order report — the user-given "API_PRODUCTION_ORDER_2_SRV" does not exist in
// this landscape (HTTP 403); MPE_PRODORDER_OBJPG_SRV/C_MfgOrderObjPg (the real live Manufacturing
// Order object-page Fiori app service) is the genuine live equivalent.
async function buildPpProductionOrderReport(query: string): Promise<{ text: string; toolResults: ToolResult[] } | null> {
  const q = normalizeSdPrompt(query);
  const orderMatch = query.match(/(?:production\s*order|order)\s*(?:number|#)?\s*[:#]?\s*(\d{8,12})/i);
  const materialMatch = query.match(new RegExp(`material\\s*(?:number|#)?\\s*[:#]?\\s*${MM_ID_RE.source}`, 'i'));
  const select = '$select=ProductionOrder,ProductionPlant,SystemStatusText,Material,MaterialName,ProductionUnit,TotalQuantity,ManufacturingOrderType,MfgOrderConfirmedYieldQty,MfgOrderPlannedStartDate,MfgOrderPlannedEndDate,MRPController,ProductionSupervisor';
  const conditions: string[] = [];
  if (orderMatch) conditions.push(`ProductionOrder eq '${orderMatch[1].trim()}'`);
  if (materialMatch) conditions.push(`Material eq '${materialMatch[1].trim()}'`);
  let filter = `${select}&$top=500`;
  if (conditions.length) filter = `${select}&$filter=${conditions.join(' and ')}&$top=200`;
  const res = await sapApi.queryS8HOData('MPE_PRODORDER_OBJPG_SRV', 'C_MfgOrderObjPg', filter);
  if (res?.error || !Array.isArray(res)) return null;
  let rows = [...res];
  const todayIso = new Date().toISOString().slice(0, 10);
  if (q.includes('released') || q.includes('release')) rows = rows.filter((r: any) => /rel/i.test(String(r.SystemStatusText || '')));
  else if (q.includes('completed') || q.includes('teco')) rows = rows.filter((r: any) => /teco|clsd|closed|complet/i.test(String(r.SystemStatusText || '')));
  else if (q.includes('not yet released') || q.includes('not released')) rows = rows.filter((r: any) => !/rel/i.test(String(r.SystemStatusText || '')));
  else if (q.includes('partial')) rows = rows.filter((r: any) => Number(r.MfgOrderConfirmedYieldQty) > 0 && Number(r.MfgOrderConfirmedYieldQty) < Number(r.TotalQuantity));
  else if (q.includes('delayed') || q.includes('behind schedule')) rows = rows.filter((r: any) => { const end = odataDateToIso(r.MfgOrderPlannedEndDate); return typeof end === 'string' && end < todayIso && !/teco|clsd|closed|complet/i.test(String(r.SystemStatusText || '')); });
  else if (q.includes('at risk') || q.includes('missing their delivery')) {
    const in3Days = new Date(); in3Days.setDate(in3Days.getDate() + 3);
    const in3DaysIso = in3Days.toISOString().slice(0, 10);
    rows = rows.filter((r: any) => { const end = odataDateToIso(r.MfgOrderPlannedEndDate); return typeof end === 'string' && end >= todayIso && end <= in3DaysIso && !/teco|clsd|closed|complet/i.test(String(r.SystemStatusText || '')); });
  } else if (q.includes('today') || q.includes('manufacture today')) rows = rows.filter((r: any) => odataDateToIso(r.MfgOrderPlannedStartDate) === todayIso);
  else if (q.includes('this week') || q.includes('week')) {
    const weekEnd = new Date(); weekEnd.setDate(weekEnd.getDate() + 7);
    const weekEndIso = weekEnd.toISOString().slice(0, 10);
    rows = rows.filter((r: any) => { const start = odataDateToIso(r.MfgOrderPlannedStartDate); return typeof start === 'string' && start >= todayIso && start <= weekEndIso; });
  }
  const displayRows = rows.slice(0, 50).map((r: any) => ({
    order: r.ProductionOrder, plant: r.ProductionPlant, status: r.SystemStatusText || '\u2014',
    material: `${r.Material} \u2014 ${r.MaterialName || ''}`.trim(), qty: r.TotalQuantity, unit: r.ProductionUnit,
    orderType: r.ManufacturingOrderType, confirmedYield: r.MfgOrderConfirmedYieldQty,
    plannedStart: odataDateToIso(r.MfgOrderPlannedStartDate) || '\u2014', plannedEnd: odataDateToIso(r.MfgOrderPlannedEndDate) || '\u2014', mrpController: r.MRPController
  }));
  return buildMmReportResult('queryLiveS8HOData',
    `Live MPE_PRODORDER_OBJPG_SRV/C_MfgOrderObjPg sampled ${res.length} real Production Order(s); ${rows.length} match the current filter.`,
    'Live Production Orders (MPE_PRODORDER_OBJPG_SRV)',
    [{ label: 'Orders Sampled', value: String(res.length) }, { label: 'Matching Filter', value: String(rows.length) }],
    [{ key: 'order', label: 'Production Order' }, { key: 'plant', label: 'Plant' }, { key: 'status', label: 'Status' }, { key: 'material', label: 'Material' }, { key: 'qty', label: 'Total Qty' }, { key: 'unit', label: 'Unit' }, { key: 'orderType', label: 'Order Type' }, { key: 'confirmedYield', label: 'Confirmed Yield' }, { key: 'plannedStart', label: 'Planned Start' }, { key: 'plannedEnd', label: 'Planned End' }, { key: 'mrpController', label: 'MRP Controller' }],
    displayRows,
    'The standard "API_PRODUCTION_ORDER_2_SRV" name is not deployed in this landscape (HTTP 403) \u2014 MPE_PRODORDER_OBJPG_SRV/C_MfgOrderObjPg (the real live Manufacturing Order object-page service) is the genuine live equivalent.'
  );
}

