  const materialMatch = query.match(new RegExp(`material\\s*(?:number|#)?\\s*[:#]?\\s*${MM_ID_RE.source}`, 'i'));
  const select = '$select=PlannedOrder,Material,MaterialName,ProductionPlant,ProductionVersion,TotalQuantity,BaseUnit,PlannedOrderType,PlndOrderPlannedStartDate,PlndOrderPlannedEndDate,MRPController,PlannedOrderIsFirm,PlannedOrderIsConvertible';
