// Live Demand Management / Supply-Demand list report — genuinely API_MRP_MATERIALS_SRV_01/
// SupplyDemandItems (real per-material MRP element list, the genuine live substitute for both
// generic "Demand Management" and, when a real Planned Independent Requirement element exists,
// Planned Independent Requirements/PIR \u2014 the exact "API_PLNDIND_RQMT_SRV" name is HTTP 403 in
// this landscape). This entity REQUIRES a real Material+MRPPlant filter (confirmed live: a bare
// query returns real HTTP 400 "Selection is empty"), so one is resolved first via a real live
// MRP material lookup if not explicitly given.
async function buildPpSupplyDemandReport(query: string): Promise<{ text: string; toolResults: ToolResult[] } | null> {
  const materialMatch = query.match(new RegExp(`material\\s*(?:number|#)?\\s*[:#]?\\s*${MM_ID_RE.source}`, 'i'));
  let material: string | null = materialMatch ? materialMatch[1].trim() : null;
  let mrpPlant: string | null = null;
  if (material) {
    const lookup = await sapApi.queryS8HOData('API_MRP_MATERIALS_SRV_01', 'A_MRPMaterial', `$select=Material,MRPPlant&$filter=Material eq '${material}'&$top=1`);
    if (Array.isArray(lookup) && lookup.length) mrpPlant = lookup[0].MRPPlant;
  }
  if (!material || !mrpPlant) {
    const sample = await sapApi.queryS8HOData('API_MRP_MATERIALS_SRV_01', 'A_MRPMaterial', `$select=Material,MRPPlant&$top=1`);
    if (Array.isArray(sample) && sample.length) { material = sample[0].Material; mrpPlant = sample[0].MRPPlant; }
  }
  if (!material || !mrpPlant) return null;
  const res = await sapApi.queryS8HOData('API_MRP_MATERIALS_SRV_01', 'SupplyDemandItems', `$filter=Material eq '${material}' and MRPPlant eq '${mrpPlant}'&$top=200`);
  if (res?.error || !Array.isArray(res)) return null;
  const rows = res.slice(0, 50).map((r: any) => ({
    material: r.Material, plant: r.MRPPlant, mrpArea: r.MRPArea, elementCategory: r.MRPElementCategoryName || r.MRPElementCategory,
    element: r.MRPElement || '\u2014', date: odataDateToIso(r.MRPElementAvailyOrRqmtDate) || '\u2014',
    openQty: r.MRPElementOpenQuantity, availableQty: r.MRPAvailableQuantity, unit: r.MaterialBaseUnit, released: (r.MRPElementIsReleased === true || r.MRPElementIsReleased === 'true') ? 'Yes' : 'No'
  }));
  return buildMmReportResult('queryLiveS8HOData',
    `Live API_MRP_MATERIALS_SRV_01/SupplyDemandItems for Material ${material} (Plant ${mrpPlant}) found ${res.length} real supply/demand element(s).`,
    `Live Supply/Demand Elements \u2014 Material ${material} (API_MRP_MATERIALS_SRV_01)`,
    [{ label: 'Elements Found', value: String(res.length) }],
    [{ key: 'material', label: 'Material' }, { key: 'plant', label: 'Plant' }, { key: 'mrpArea', label: 'MRP Area' }, { key: 'elementCategory', label: 'Element Category' }, { key: 'element', label: 'MRP Element' }, { key: 'date', label: 'Avail./Reqmt Date' }, { key: 'openQty', label: 'Open Qty' }, { key: 'availableQty', label: 'Available Qty' }, { key: 'unit', label: 'Unit' }, { key: 'released', label: 'Released?' }],
    rows,
    'The exact "API_PLNDIND_RQMT_SRV" (Planned Independent Requirements) name is not deployed in this landscape (HTTP 403) \u2014 API_MRP_MATERIALS_SRV_01/SupplyDemandItems (the real live per-material MRP element list, which includes PIR elements when they exist via MRPElementCategory) is the genuine live equivalent for both Demand Management and PIR.'
  );
}

