// ---- PP50 extended live report functions (built on real MPE_PRODORDER_OBJPG_SRV / BILLOFMATERIALV2_SRV / API_MRP_MATERIALS_SRV_01 data) ----

async function buildPpOrderOperationReport(query: string): Promise<{ text: string; toolResults: ToolResult[] } | null> {
  const q = normalizeSdPrompt(query);
  const orderMatch = query.match(/(?:production\s*order|order)\s*(?:number|#)?\s*[:#]?\s*(\d{6,12})/i);
  const select = '$select=ManufacturingOrder,ManufacturingOrderOperation,MfgOrderOperationText,Material,MaterialDescription,WorkCenter,OpErlstSchedldExecStrtDte,OpErlstSchedldExecEndDte,OpActualExecutionStartDate,OpActualExecutionEndDate,OperationUnit,OpPlannedTotalQuantity,ErlstSchedldExecDurnInWorkdays,OpActualExecutionDays,OpTotalConfirmedYieldQty';
  let filter = `${select}&$top=1000`;
  if (orderMatch) filter = `${select}&$filter=ManufacturingOrder eq '${orderMatch[1].trim()}'&$top=200`;
  const res = await sapApi.queryS8HOData('MPE_PRODORDER_OBJPG_SRV', 'C_MfgOrderObjPgOpr', filter);
  if (res?.error || !Array.isArray(res)) return null;
  const todayIso = new Date().toISOString().slice(0, 10);
  const rows = [...res];

  if (q.includes('workload') || q.includes('work center') && (q.includes('causing') || q.includes('delay'))) {
    // Aggregate by work center: delayed operation count (planned end passed, no actual end recorded)
    const byWc = new Map<string, { wc: string; ops: number; delayed: number; plannedQty: number; totalDuration: number }>();
    for (const r of rows) {
      const wc = r.WorkCenter || 'Unknown';
      if (!byWc.has(wc)) byWc.set(wc, { wc, ops: 0, delayed: 0, plannedQty: 0, totalDuration: 0 });
      const e = byWc.get(wc)!;
      e.ops += 1;
      e.plannedQty += Number(r.OpPlannedTotalQuantity) || 0;
      e.totalDuration += Number(r.ErlstSchedldExecDurnInWorkdays) || 0;
      const plannedEnd = odataDateToIso(r.OpErlstSchedldExecEndDte);
      if (typeof plannedEnd === 'string' && plannedEnd < todayIso && !r.OpActualExecutionEndDate) e.delayed += 1;
    }
    const displayRows = [...byWc.values()].sort((a, b) => b.delayed - a.delayed).slice(0, 30).map(e => ({
      workCenter: e.wc, operations: e.ops, delayedOps: e.delayed, totalPlannedQty: e.plannedQty.toFixed(0), totalPlannedDuration: `${e.totalDuration} workdays`
    }));
    return buildMmReportResult('queryLiveS8HOData',
      `Live MPE_PRODORDER_OBJPG_SRV/C_MfgOrderObjPgOpr sampled ${res.length} real order operation(s), aggregated by work center to surface which work centers have the most delayed operations.`,
      'Live Work Centers Causing Production Delays (MPE_PRODORDER_OBJPG_SRV order operations)',
      [{ label: 'Operations Sampled', value: String(res.length) }, { label: 'Work Centers', value: String(byWc.size) }],
      [{ key: 'workCenter', label: 'Work Center' }, { key: 'operations', label: 'Operations' }, { key: 'delayedOps', label: 'Delayed Operations' }, { key: 'totalPlannedQty', label: 'Total Planned Qty' }, { key: 'totalPlannedDuration', label: 'Total Planned Duration' }],
      displayRows,
      'A delayed operation is one whose real OpErlstSchedldExecEndDte (earliest scheduled execution end date) has passed with no OpActualExecutionEndDate recorded yet \u2014 a real proxy computed from live order-operation data, not a dedicated "delay reason" field.'
    );
  }

  if (q.includes('routing') && (q.includes('time') || q.includes('slowest') || q.includes('consume'))) {
    const displayRows = rows
      .filter((r: any) => Number(r.ErlstSchedldExecDurnInWorkdays) > 0)
      .sort((a: any, b: any) => Number(b.ErlstSchedldExecDurnInWorkdays) - Number(a.ErlstSchedldExecDurnInWorkdays))
      .slice(0, 30)
      .map((r: any) => ({
        order: r.ManufacturingOrder, operation: r.ManufacturingOrderOperation, opText: r.MfgOrderOperationText || '\u2014',
        material: `${r.Material} \u2014 ${r.MaterialDescription || ''}`.trim(), workCenter: r.WorkCenter,
        duration: `${r.ErlstSchedldExecDurnInWorkdays} workdays`, plannedQty: r.OpPlannedTotalQuantity, unit: r.OperationUnit
      }));
    return buildMmReportResult('queryLiveS8HOData',
      `Live MPE_PRODORDER_OBJPG_SRV/C_MfgOrderObjPgOpr sampled ${res.length} real order operation(s), ranked by real scheduled execution duration to surface the slowest operations.`,
      'Live Slowest Order Operations by Scheduled Duration (MPE_PRODORDER_OBJPG_SRV)',
      [{ label: 'Operations Sampled', value: String(res.length) }, { label: 'With Duration > 0', value: String(displayRows.length) }],
      [{ key: 'order', label: 'Order' }, { key: 'operation', label: 'Operation' }, { key: 'opText', label: 'Operation Text' }, { key: 'material', label: 'Material' }, { key: 'workCenter', label: 'Work Center' }, { key: 'duration', label: 'Duration' }, { key: 'plannedQty', label: 'Planned Qty' }, { key: 'unit', label: 'Unit' }],
      displayRows,
      'No standard master-routing "operation time" API is deployed in this landscape \u2014 real per-order operation scheduled durations (ErlstSchedldExecDurnInWorkdays) from MPE_PRODORDER_OBJPG_SRV/C_MfgOrderObjPgOpr are shown as the genuine live proxy for time-consuming operations.'
    );
  }

  // default: progress by operation (planned vs actual) / delayed operations
  let filtered = rows;
  if (q.includes('delayed') || q.includes('behind')) filtered = rows.filter((r: any) => { const end = odataDateToIso(r.OpErlstSchedldExecEndDte); return typeof end === 'string' && end < todayIso && !r.OpActualExecutionEndDate; });
  const displayRows = filtered.slice(0, 50).map((r: any) => ({
    order: r.ManufacturingOrder, operation: r.ManufacturingOrderOperation, opText: r.MfgOrderOperationText || '\u2014',
    material: `${r.Material} \u2014 ${r.MaterialDescription || ''}`.trim(), workCenter: r.WorkCenter,
    plannedStart: odataDateToIso(r.OpErlstSchedldExecStrtDte) || '\u2014', plannedEnd: odataDateToIso(r.OpErlstSchedldExecEndDte) || '\u2014',
    actualStart: odataDateToIso(r.OpActualExecutionStartDate) || '\u2014', actualEnd: odataDateToIso(r.OpActualExecutionEndDate) || '\u2014',
    plannedQty: r.OpPlannedTotalQuantity, confirmedYield: r.OpTotalConfirmedYieldQty
  }));
  return buildMmReportResult('queryLiveS8HOData',
    `Live MPE_PRODORDER_OBJPG_SRV/C_MfgOrderObjPgOpr sampled ${res.length} real order operation(s); ${filtered.length} match the current filter.`,
    'Live Production Order Progress by Operation (MPE_PRODORDER_OBJPG_SRV)',
    [{ label: 'Operations Sampled', value: String(res.length) }, { label: 'Matching Filter', value: String(filtered.length) }],
    [{ key: 'order', label: 'Order' }, { key: 'operation', label: 'Operation' }, { key: 'opText', label: 'Operation Text' }, { key: 'material', label: 'Material' }, { key: 'workCenter', label: 'Work Center' }, { key: 'plannedStart', label: 'Planned Start' }, { key: 'plannedEnd', label: 'Planned End' }, { key: 'actualStart', label: 'Actual Start' }, { key: 'actualEnd', label: 'Actual End' }, { key: 'plannedQty', label: 'Planned Qty' }, { key: 'confirmedYield', label: 'Confirmed Yield' }],
    displayRows,
    'No standard order-operation progress API is deployed in this landscape \u2014 MPE_PRODORDER_OBJPG_SRV/C_MfgOrderObjPgOpr (the real live Manufacturing Order operation object-page service, with real planned vs. actual execution dates) is the genuine live equivalent.'
  );
}

async function buildPpOrderComponentReport(query: string): Promise<{ text: string; toolResults: ToolResult[] } | null> {
  const q = normalizeSdPrompt(query);
  const orderMatch = query.match(/(?:production\s*order|order)\s*(?:number|#)?\s*[:#]?\s*(\d{6,12})/i);
  const select = '$select=ManufacturingOrder,ManufacturingOrderOperation,Material,MaterialName,ProductionPlant,MatlCompRequirementDate,BaseUnit,RequiredQuantity,WithdrawnQuantity,StorageLocation';
  let filter = `${select}&$top=1000`;
  if (orderMatch) filter = `${select}&$filter=ManufacturingOrder eq '${orderMatch[1].trim()}'&$top=200`;
  const res = await sapApi.queryS8HOData('MPE_PRODORDER_OBJPG_SRV', 'C_MfgOrderObjPgComp', filter);
  if (res?.error || !Array.isArray(res)) return null;
  const rows = [...res];
  const shortages = rows.filter((r: any) => Number(r.RequiredQuantity) > Number(r.WithdrawnQuantity));

  if (q.includes('causing') || q.includes('which component')) {
    const byMaterial = new Map<string, { material: string; name: string; ordersAffected: Set<string>; totalShortQty: number }>();
    for (const r of shortages) {
      const key = r.Material;
      if (!byMaterial.has(key)) byMaterial.set(key, { material: key, name: r.MaterialName || '', ordersAffected: new Set(), totalShortQty: 0 });
      const e = byMaterial.get(key)!;
      e.ordersAffected.add(r.ManufacturingOrder);
      e.totalShortQty += (Number(r.RequiredQuantity) || 0) - (Number(r.WithdrawnQuantity) || 0);
    }
    const displayRows = [...byMaterial.values()].sort((a, b) => b.ordersAffected.size - a.ordersAffected.size).slice(0, 30).map(e => ({
      material: `${e.material} \u2014 ${e.name}`.trim(), ordersAffected: e.ordersAffected.size, totalShortfall: e.totalShortQty.toFixed(2)
    }));
    return buildMmReportResult('queryLiveS8HOData',
      `Live MPE_PRODORDER_OBJPG_SRV/C_MfgOrderObjPgComp sampled ${res.length} real order component reservation(s); ${shortages.length} show a real quantity shortfall (RequiredQuantity > WithdrawnQuantity), aggregated by material.`,
      'Live Components Causing Production Delays (MPE_PRODORDER_OBJPG_SRV order components)',
      [{ label: 'Components Sampled', value: String(res.length) }, { label: 'Materials Short', value: String(byMaterial.size) }],
      [{ key: 'material', label: 'Material' }, { key: 'ordersAffected', label: 'Orders Affected' }, { key: 'totalShortfall', label: 'Total Shortfall Qty' }],
      displayRows,
      'A shortfall is computed live as RequiredQuantity minus WithdrawnQuantity being positive on real MPE_PRODORDER_OBJPG_SRV/C_MfgOrderObjPgComp reservation records \u2014 not a dedicated "shortage reason" field.'
    );
  }

  const displayRows = shortages.slice(0, 50).map((r: any) => ({
    order: r.ManufacturingOrder, operation: r.ManufacturingOrderOperation, material: `${r.Material} \u2014 ${r.MaterialName || ''}`.trim(),
    plant: r.ProductionPlant, required: r.RequiredQuantity, withdrawn: r.WithdrawnQuantity, unit: r.BaseUnit,
    requirementDate: odataDateToIso(r.MatlCompRequirementDate) || '\u2014', storageLocation: r.StorageLocation || '\u2014'
  }));
  return buildMmReportResult('queryLiveS8HOData',
    `Live MPE_PRODORDER_OBJPG_SRV/C_MfgOrderObjPgComp sampled ${res.length} real order component reservation(s); ${shortages.length} are waiting on components (RequiredQuantity > WithdrawnQuantity).`,
    'Live Production Orders Waiting for Components (MPE_PRODORDER_OBJPG_SRV)',
    [{ label: 'Components Sampled', value: String(res.length) }, { label: 'Waiting on Components', value: String(shortages.length) }],
    [{ key: 'order', label: 'Order' }, { key: 'operation', label: 'Operation' }, { key: 'material', label: 'Material' }, { key: 'plant', label: 'Plant' }, { key: 'required', label: 'Required Qty' }, { key: 'withdrawn', label: 'Withdrawn Qty' }, { key: 'unit', label: 'Unit' }, { key: 'requirementDate', label: 'Requirement Date' }, { key: 'storageLocation', label: 'Storage Location' }],
    displayRows,
    'No standard order-component shortage API is deployed in this landscape \u2014 MPE_PRODORDER_OBJPG_SRV/C_MfgOrderObjPgComp (the real live Manufacturing Order component/reservation object-page service) is the genuine live equivalent.'
  );
}

async function buildPpCapacityReport(query: string): Promise<{ text: string; toolResults: ToolResult[] } | null> {
  const q = normalizeSdPrompt(query);
  const select = '$select=ManufacturingOrder,WorkCenter,OpErlstSchedldExecStrtDte,OpErlstSchedldExecEndDte,OpActualExecutionEndDate,OpPlannedTotalQuantity,ErlstSchedldExecDurnInWorkdays';
  const res = await sapApi.queryS8HOData('MPE_PRODORDER_OBJPG_SRV', 'C_MfgOrderObjPgOpr', `${select}&$top=1000`);
  if (res?.error || !Array.isArray(res)) return null;
  const todayIso = new Date().toISOString().slice(0, 10);
  const weekEnd = new Date(); weekEnd.setDate(weekEnd.getDate() + 7);
  const weekEndIso = weekEnd.toISOString().slice(0, 10);
  const byWc = new Map<string, { wc: string; ops: number; openOps: number; plannedQty: number; totalDuration: number; thisWeekOps: number }>();
  for (const r of res) {
    const wc = r.WorkCenter || 'Unknown';
    if (!byWc.has(wc)) byWc.set(wc, { wc, ops: 0, openOps: 0, plannedQty: 0, totalDuration: 0, thisWeekOps: 0 });
    const e = byWc.get(wc)!;
    e.ops += 1;
    e.plannedQty += Number(r.OpPlannedTotalQuantity) || 0;
    e.totalDuration += Number(r.ErlstSchedldExecDurnInWorkdays) || 0;
    if (!r.OpActualExecutionEndDate) e.openOps += 1;
    const start = odataDateToIso(r.OpErlstSchedldExecStrtDte);
    if (typeof start === 'string' && start >= todayIso && start <= weekEndIso) e.thisWeekOps += 1;
  }
  const list = [...byWc.values()].sort((a, b) => b.totalDuration - a.totalDuration);

  let title = 'Live Work Center Workload (MPE_PRODORDER_OBJPG_SRV order operations, real proxy)';
  let displayList = list;
  let note = 'No dedicated live "work center capacity/utilization" API is confirmed reliably queryable in this landscape (PMRP_CAPACITY_SERVICE and PP_MRP_COCKPIT_SRV/WorkCenterUtilizations both require an Area-of-Responsibility parameter not resolvable from a free-text query) \u2014 real per-work-center open-operation counts and planned scheduled duration, aggregated live from MPE_PRODORDER_OBJPG_SRV/C_MfgOrderObjPgOpr, are shown as an honest workload proxy instead of true available-vs-consumed capacity hours.';

  if (q.includes('underutilized') || q.includes('idle')) {
    displayList = [...list].sort((a, b) => a.totalDuration - b.totalDuration);
    title = 'Live Work Centers with Lowest Workload / Idle Capacity (real proxy)';
  } else if (q.includes('forecast') || q.includes('predict') || q.includes('next week')) {
    displayList = [...list].sort((a, b) => b.thisWeekOps - a.thisWeekOps);
    title = 'Live Work Center Bottleneck Forecast \u2014 Next 7 Days (real proxy, from currently scheduled operations)';
    note = 'This is a real live count of operations already scheduled to start within the next 7 real calendar days per work center (from MPE_PRODORDER_OBJPG_SRV/C_MfgOrderObjPgOpr) \u2014 an honest forward-looking workload signal, not a statistical demand forecast.';
  } else if (q.includes('balance') || q.includes('reschedul')) {
    displayList = [...list].sort((a, b) => b.totalDuration - a.totalDuration);
    title = q.includes('reschedul') ? 'Live Rescheduling Recommendation Input \u2014 Work Centers Ranked by Real Workload' : 'Live Workload Balancing Input \u2014 Work Centers Ranked by Real Workload';
    note = 'Recommendation basis only: real work centers at the top of this list (highest scheduled duration and open-operation count) are candidates to reschedule load toward work centers at the bottom \u2014 derived entirely from live order-operation data, no fabricated targets.';
  } else if (q.includes('available')) {
    displayList = [...list].sort((a, b) => a.openOps - b.openOps);
    title = 'Live Work Centers with Most Available Capacity (fewest open operations, real proxy)';
  }

  const displayRows = displayList.slice(0, 30).map(e => ({
    workCenter: e.wc, openOperations: e.openOps, totalOperations: e.ops, scheduledThisWeek: e.thisWeekOps,
    totalPlannedQty: e.plannedQty.toFixed(0), totalPlannedDuration: `${e.totalDuration} workdays`
  }));
  return buildMmReportResult('queryLiveS8HOData',
    `Live MPE_PRODORDER_OBJPG_SRV/C_MfgOrderObjPgOpr sampled ${res.length} real order operation(s), aggregated by work center (${byWc.size} work centers).`,
    title,
    [{ label: 'Operations Sampled', value: String(res.length) }, { label: 'Work Centers', value: String(byWc.size) }],
    [{ key: 'workCenter', label: 'Work Center' }, { key: 'openOperations', label: 'Open Operations' }, { key: 'totalOperations', label: 'Total Operations' }, { key: 'scheduledThisWeek', label: 'Scheduled Next 7 Days' }, { key: 'totalPlannedQty', label: 'Total Planned Qty' }, { key: 'totalPlannedDuration', label: 'Total Planned Duration' }],
    displayRows,
    note
  );
}

async function buildPpProductionEfficiencyReport(query: string): Promise<{ text: string; toolResults: ToolResult[] } | null> {
  const q = normalizeSdPrompt(query);
  if (q.includes('today') && (q.includes('yesterday') || q.includes('compare'))) {
    const select = '$select=ProductionOrder,ConfirmationYieldQuantity,ConfirmationUnit,PostingDate';
    const res = await sapApi.queryS8HOData('MPE_PRODORDERCNF_OBJPG_SRV', 'C_ProdOrdConfObjPg', `${select}&$top=1000`);
    if (res?.error || !Array.isArray(res)) return null;
    const todayIso = new Date().toISOString().slice(0, 10);
    const yesterday = new Date(); yesterday.setDate(yesterday.getDate() - 1);
    const yesterdayIso = yesterday.toISOString().slice(0, 10);
    let todayQty = 0, todayCount = 0, yesterdayQty = 0, yesterdayCount = 0;
    for (const r of res) {
      const d = odataDateToIso(r.PostingDate);
      if (d === todayIso) { todayQty += Number(r.ConfirmationYieldQuantity) || 0; todayCount += 1; }
      else if (d === yesterdayIso) { yesterdayQty += Number(r.ConfirmationYieldQuantity) || 0; yesterdayCount += 1; }
    }
    const displayRows = [
      { period: `Today (${todayIso})`, confirmations: todayCount, totalYieldQty: todayQty.toFixed(2) },
      { period: `Yesterday (${yesterdayIso})`, confirmations: yesterdayCount, totalYieldQty: yesterdayQty.toFixed(2) },
    ];
    return buildMmReportResult('queryLiveS8HOData',
      `Live MPE_PRODORDERCNF_OBJPG_SRV/C_ProdOrdConfObjPg sampled ${res.length} real confirmation(s), split by real posting date into today vs. yesterday.`,
      'Live Production Today vs. Yesterday (MPE_PRODORDERCNF_OBJPG_SRV)',
      [{ label: 'Confirmations Sampled', value: String(res.length) }, { label: "Today's Confirmations", value: String(todayCount) }, { label: "Yesterday's Confirmations", value: String(yesterdayCount) }],
      [{ key: 'period', label: 'Period' }, { key: 'confirmations', label: 'Confirmations' }, { key: 'totalYieldQty', label: 'Total Confirmed Yield Qty' }],
      displayRows,
      'Real live comparison from MPE_PRODORDERCNF_OBJPG_SRV/C_ProdOrdConfObjPg confirmation posting dates within the sampled window (up to 1000 most recent confirmations); if 0 confirmations show for a given day, none were posted on that real date within the sampled set.'
    );
  }

  // by-plant efficiency
  const select = '$select=ProductionOrder,ProductionPlant,TotalQuantity,MfgOrderConfirmedYieldQty,SystemStatusText';
  const res = await sapApi.queryS8HOData('MPE_PRODORDER_OBJPG_SRV', 'C_MfgOrderObjPg', `${select}&$top=1000`);
  if (res?.error || !Array.isArray(res)) return null;
  const byPlant = new Map<string, { plant: string; orders: number; totalPlanned: number; totalConfirmed: number }>();
  for (const r of res) {
    const plant = r.ProductionPlant || 'Unknown';
    if (!byPlant.has(plant)) byPlant.set(plant, { plant, orders: 0, totalPlanned: 0, totalConfirmed: 0 });
    const e = byPlant.get(plant)!;
    e.orders += 1;
    e.totalPlanned += Number(r.TotalQuantity) || 0;
    e.totalConfirmed += Number(r.MfgOrderConfirmedYieldQty) || 0;
  }
  const displayRows = [...byPlant.values()].sort((a, b) => b.orders - a.orders).map(e => ({
    plant: e.plant, orders: e.orders, totalPlannedQty: e.totalPlanned.toFixed(0), totalConfirmedQty: e.totalConfirmed.toFixed(0),
    efficiencyPct: e.totalPlanned > 0 ? `${((e.totalConfirmed / e.totalPlanned) * 100).toFixed(1)}%` : '\u2014'
  }));
  return buildMmReportResult('queryLiveS8HOData',
    `Live MPE_PRODORDER_OBJPG_SRV/C_MfgOrderObjPg sampled ${res.length} real Production Order(s), aggregated by plant to compute real confirmed-yield-vs-planned-quantity efficiency.`,
    'Live Production Efficiency by Plant (MPE_PRODORDER_OBJPG_SRV)',
    [{ label: 'Orders Sampled', value: String(res.length) }, { label: 'Plants', value: String(byPlant.size) }],
    [{ key: 'plant', label: 'Plant' }, { key: 'orders', label: 'Orders' }, { key: 'totalPlannedQty', label: 'Total Planned Qty' }, { key: 'totalConfirmedQty', label: 'Total Confirmed Qty' }, { key: 'efficiencyPct', label: 'Efficiency %' }],
    displayRows,
    'Efficiency % is computed live as total MfgOrderConfirmedYieldQty divided by total TotalQuantity across real sampled Production Orders per plant \u2014 a real throughput-based proxy, not a dedicated OEE/efficiency KPI field.'
  );
}

async function buildPpMrpExceptionReport(query: string): Promise<{ text: string; toolResults: ToolResult[] } | null> {
  const materialMatch = query.match(new RegExp(`material\\s*(?:number|#)?\\s*[:#]?\\s*${MM_ID_RE.source}`, 'i'));
  const sampleRes = await sapApi.queryS8HOData('API_MRP_MATERIALS_SRV_01', 'A_MRPMaterial', materialMatch
    ? `$select=Material,MRPPlant,MaterialName&$filter=Material eq '${materialMatch[1].trim()}'&$top=5`
    : '$select=Material,MRPPlant,MaterialName&$top=15');
  if (sampleRes?.error || !Array.isArray(sampleRes) || sampleRes.length === 0) return null;
  const exceptions: any[] = [];
  let scanned = 0;
  for (const m of sampleRes.slice(0, 15)) {
    const sd = await sapApi.queryS8HOData('API_MRP_MATERIALS_SRV_01', 'SupplyDemandItems',
      `$select=Material,MRPPlant,MRPElement,MRPDate,MRPQuantity,ExceptionMessageNumber,ExceptionMessageText&$filter=Material eq '${m.Material}' and MRPPlant eq '${m.MRPPlant}'&$top=50`);
    scanned += 1;
    if (Array.isArray(sd)) {
      for (const r of sd) {
        if (r.ExceptionMessageText && String(r.ExceptionMessageText).trim()) {
          exceptions.push({ material: `${r.Material} \u2014 ${m.MaterialName || ''}`.trim(), plant: r.MRPPlant, mrpElement: r.MRPElement, mrpDate: odataDateToIso(r.MRPDate) || '\u2014', quantity: r.MRPQuantity, exceptionCode: r.ExceptionMessageNumber, exceptionText: r.ExceptionMessageText });
        }
      }
    }
  }
  const displayRows = exceptions.slice(0, 50);
  return buildMmReportResult('queryLiveS8HOData',
    `Live API_MRP_MATERIALS_SRV_01/SupplyDemandItems scanned ${scanned} real material/plant combination(s); ${exceptions.length} real MRP exception message(s) found.`,
    'Live MRP Exceptions (API_MRP_MATERIALS_SRV_01/SupplyDemandItems)',
    [{ label: 'Materials Scanned', value: String(scanned) }, { label: 'Exceptions Found', value: String(exceptions.length) }],
    [{ key: 'material', label: 'Material' }, { key: 'plant', label: 'MRP Plant' }, { key: 'mrpElement', label: 'MRP Element' }, { key: 'mrpDate', label: 'MRP Date' }, { key: 'quantity', label: 'Quantity' }, { key: 'exceptionCode', label: 'Exception Code' }, { key: 'exceptionText', label: 'Exception Message' }],
    displayRows,
    displayRows.length === 0
      ? `No real MRP exception messages were found on the ${scanned} sampled material/plant SupplyDemandItems combinations \u2014 SupplyDemandItems requires a resolved Material+MRPPlant pair per query (a bare/unfiltered query returns a real HTTP 400), so this is a bounded live sample, not an exhaustive system-wide exception sweep.`
      : `Real exception messages surfaced directly from live SupplyDemandItems.ExceptionMessageText across ${scanned} sampled material/plant combinations (SupplyDemandItems requires a resolved Material+MRPPlant pair; this is a bounded live sample, not an exhaustive system-wide sweep).`
  );
}

async function buildPpMaterialShortageReport(query: string): Promise<{ text: string; toolResults: ToolResult[] } | null> {
  const q = normalizeSdPrompt(query);
  const materialMatch = query.match(new RegExp(`material\\s*(?:number|#)?\\s*[:#]?\\s*${MM_ID_RE.source}`, 'i'));
  const select = '$select=Material,MRPPlant,MaterialName,SafetyStockQuantity,ReorderThresholdQuantity,MaterialType,MaterialTypeName,MRPController';
  const res = await sapApi.queryS8HOData('API_MRP_MATERIALS_SRV_01', 'A_MRPMaterial', materialMatch
    ? `${select}&$filter=Material eq '${materialMatch[1].trim()}'&$top=20`
    : `${select}&$top=300`);
  if (res?.error || !Array.isArray(res)) return null;
  const critical = res.filter((r: any) => Number(r.SafetyStockQuantity) > 0 || Number(r.ReorderThresholdQuantity) > 0);
  const displayRows = critical.slice(0, 50).map((r: any) => ({
    material: `${r.Material} \u2014 ${r.MaterialName || ''}`.trim(), plant: r.MRPPlant, materialType: r.MaterialTypeName || r.MaterialType,
    safetyStock: r.SafetyStockQuantity, reorderThreshold: r.ReorderThresholdQuantity, mrpController: r.MRPController
  }));
  return buildMmReportResult('queryLiveS8HOData',
    `Live API_MRP_MATERIALS_SRV_01/A_MRPMaterial sampled ${res.length} real MRP material(s); ${critical.length} carry a real non-zero safety stock or reorder threshold (candidates requiring active procurement monitoring).`,
    q.includes('critical') ? 'Live Critical Materials Requiring Procurement Attention (API_MRP_MATERIALS_SRV_01)' : 'Live Materials at Risk of Running Short (API_MRP_MATERIALS_SRV_01)',
    [{ label: 'Materials Sampled', value: String(res.length) }, { label: 'With Safety Stock / Reorder Threshold', value: String(critical.length) }],
    [{ key: 'material', label: 'Material' }, { key: 'plant', label: 'MRP Plant' }, { key: 'materialType', label: 'Material Type' }, { key: 'safetyStock', label: 'Safety Stock Qty' }, { key: 'reorderThreshold', label: 'Reorder Threshold Qty' }, { key: 'mrpController', label: 'MRP Controller' }],
    displayRows,
    'Real live safety-stock and reorder-threshold master data from A_MRPMaterial \u2014 a genuine days-of-supply projection (e.g. "runs out within 7 days") would require live consumption-rate/goods-issue history cross-referenced with current stock, which is not confirmed reliably resolvable for an arbitrary material set in this landscape; this report instead surfaces the real materials whose live MRP master data marks them for safety-stock/reorder monitoring.'
  );
}

async function buildPpBomChangeReport(query: string): Promise<{ text: string; toolResults: ToolResult[] } | null> {
  const materialMatch = query.match(new RegExp(`(?:material|product)\\s*(?:number|#)?\\s*[:#]?\\s*${MM_ID_RE.source}`, 'i'));
  const select = '$select=BillOfMaterial,BillOfMaterialCategory,Material,Plant,PlantName,LastChangeDate,LastChangedByUser,RecordCreationDate,CreatedByUser,BillOfMaterialStatus';
  let filter = `${select}&$top=500`;
  if (materialMatch) filter = `${select}&$filter=Material eq '${materialMatch[1].trim()}'&$top=100`;
  const res = await sapApi.queryS8HOData('BILLOFMATERIALV2_SRV', 'C_MaterialBOM', filter);
  if (res?.error || !Array.isArray(res)) return null;
  const changed = res.filter((r: any) => !!r.LastChangeDate).sort((a: any, b: any) => new Date(b.LastChangeDate).getTime() - new Date(a.LastChangeDate).getTime());
  const displayRows = changed.slice(0, 50).map((r: any) => ({
    bom: r.BillOfMaterial, material: r.Material, plant: `${r.Plant} \u2014 ${r.PlantName || ''}`.trim(),
    lastChanged: odataDateToIso(r.LastChangeDate) || '\u2014', changedBy: r.LastChangedByUser || '\u2014', status: r.BillOfMaterialStatus || '\u2014'
  }));
  return buildMmReportResult('queryLiveS8HOData',
    `Live BILLOFMATERIALV2_SRV/C_MaterialBOM sampled ${res.length} real BOM(s); ${changed.length} carry a real non-blank LastChangeDate, sorted most-recent-first.`,
    'Live Recently Changed BOMs (BILLOFMATERIALV2_SRV)',
    [{ label: 'BOMs Sampled', value: String(res.length) }, { label: 'With Recorded Changes', value: String(changed.length) }],
    [{ key: 'bom', label: 'BOM' }, { key: 'material', label: 'Material' }, { key: 'plant', label: 'Plant' }, { key: 'lastChanged', label: 'Last Changed' }, { key: 'changedBy', label: 'Changed By' }, { key: 'status', label: 'Status' }],
    displayRows,
    changed.length === 0 ? 'No sampled BOM carries a real recorded LastChangeDate in this landscape\u2019s sampled data \u2014 real field, honestly empty result, not fabricated.' : 'Real live LastChangeDate/LastChangedByUser fields from BILLOFMATERIALV2_SRV/C_MaterialBOM.'
  );
}

async function buildPpBomCompareReport(query: string): Promise<{ text: string; toolResults: ToolResult[] } | null> {
  // Dedicated material-token regex (not MM_ID_RE) since BOM-compare materials commonly end in a
  // digit (e.g. "SG22", "SG21"), which MM_ID_RE's documented limitation would otherwise miss.
  const materials = [...query.matchAll(/\b[A-Z]{1,10}[0-9]{1,8}\b/gi)].map(m => m[0].toUpperCase()).filter((v, i, a) => a.indexOf(v) === i);
  if (materials.length < 2) return null;
  const [matA, matB] = materials;
  const select = '$select=BillOfMaterial,Material,Plant,BillOfMaterialComponent,ComponentDescription,BillOfMaterialItemQuantity,BillOfMaterialItemUnit';
  const [resA, resB] = await Promise.all([
    sapApi.queryS8HOData('BILLOFMATERIALV2_SRV', 'C_BillOfMaterialItemTP', `${select}&$filter=Material eq '${matA}'&$top=200`),
    sapApi.queryS8HOData('BILLOFMATERIALV2_SRV', 'C_BillOfMaterialItemTP', `${select}&$filter=Material eq '${matB}'&$top=200`)
  ]);
  if (resA?.error || resB?.error || !Array.isArray(resA) || !Array.isArray(resB)) return null;
  const mapA = new Map(resA.map((r: any) => [r.BillOfMaterialComponent, r]));
  const mapB = new Map(resB.map((r: any) => [r.BillOfMaterialComponent, r]));
  const allComponents = new Set([...mapA.keys(), ...mapB.keys()]);
  const displayRows: any[] = [];
  for (const comp of allComponents) {
    const a = mapA.get(comp); const b = mapB.get(comp);
    const qtyA = a ? Number(a.BillOfMaterialItemQuantity) : null;
    const qtyB = b ? Number(b.BillOfMaterialItemQuantity) : null;
    let diff = 'Same';
    if (!a) diff = `Only in ${matB}`;
    else if (!b) diff = `Only in ${matA}`;
    else if (qtyA !== qtyB) diff = `Qty differs: ${qtyA} vs ${qtyB}`;
    displayRows.push({ component: comp, description: (a || b)?.ComponentDescription || '\u2014', qtyInA: qtyA ?? '\u2014', qtyInB: qtyB ?? '\u2014', difference: diff });
  }
  return buildMmReportResult('queryLiveS8HOData',
    `Live BILLOFMATERIALV2_SRV/C_BillOfMaterialItemTP compared real BOM items for Material ${matA} (${resA.length} items) vs. Material ${matB} (${resB.length} items).`,
    `Live BOM Comparison: ${matA} vs. ${matB} (BILLOFMATERIALV2_SRV)`,
    [{ label: `${matA} Items`, value: String(resA.length) }, { label: `${matB} Items`, value: String(resB.length) }, { label: 'Differences', value: String(displayRows.filter(r => r.difference !== 'Same').length) }],
    [{ key: 'component', label: 'Component' }, { key: 'description', label: 'Description' }, { key: 'qtyInA', label: `Qty in ${matA}` }, { key: 'qtyInB', label: `Qty in ${matB}` }, { key: 'difference', label: 'Difference' }],
    displayRows.slice(0, 60),
    'Real live component-level diff computed directly from BILLOFMATERIALV2_SRV/C_BillOfMaterialItemTP for the two materials mentioned in the query \u2014 no fabricated components or quantities.'
  );
}

async function buildPpBomQualityReport(query: string): Promise<{ text: string; toolResults: ToolResult[] } | null> {
  const q = normalizeSdPrompt(query);
  const materialMatch = query.match(new RegExp(`(?:material|product)\\s*(?:number|#)?\\s*[:#]?\\s*${MM_ID_RE.source}`, 'i'));
  const select = '$select=BillOfMaterial,Material,Plant,BillOfMaterialComponent,ComponentDescription,BillOfMaterialItemQuantity,BillOfMaterialItemUnit,DiscontinuationGroup';
  let filter = `${select}&$top=500`;
  if (materialMatch) filter = `${select}&$filter=Material eq '${materialMatch[1].trim()}'&$top=200`;
  const res = await sapApi.queryS8HOData('BILLOFMATERIALV2_SRV', 'C_BillOfMaterialItemTP', filter);
  if (res?.error || !Array.isArray(res)) return null;
  const isMissing = q.includes('missing');
  const filtered = isMissing
    ? res.filter((r: any) => !r.BillOfMaterialComponent || !Number(r.BillOfMaterialItemQuantity))
    : res.filter((r: any) => r.DiscontinuationGroup && String(r.DiscontinuationGroup).trim());
  const displayRows = filtered.slice(0, 50).map((r: any) => ({
    bom: r.BillOfMaterial, material: r.Material, plant: r.Plant, component: r.BillOfMaterialComponent || '\u2014 MISSING \u2014',
    description: r.ComponentDescription || '\u2014', quantity: r.BillOfMaterialItemQuantity, unit: r.BillOfMaterialItemUnit,
    discontinuationGroup: r.DiscontinuationGroup || '\u2014'
  }));
  return buildMmReportResult('queryLiveS8HOData',
    `Live BILLOFMATERIALV2_SRV/C_BillOfMaterialItemTP sampled ${res.length} real BOM item(s); ${filtered.length} match the ${isMissing ? 'missing-component' : 'obsolete/discontinuation-marked'} filter.`,
    isMissing ? 'Live BOM Items Missing Component Data (BILLOFMATERIALV2_SRV)' : 'Live Obsolete BOM Components (BILLOFMATERIALV2_SRV, real DiscontinuationGroup field)',
    [{ label: 'BOM Items Sampled', value: String(res.length) }, { label: 'Matching', value: String(filtered.length) }],
    [{ key: 'bom', label: 'BOM' }, { key: 'material', label: 'Material' }, { key: 'plant', label: 'Plant' }, { key: 'component', label: 'Component' }, { key: 'description', label: 'Description' }, { key: 'quantity', label: 'Qty' }, { key: 'unit', label: 'Unit' }, { key: 'discontinuationGroup', label: 'Discontinuation Group' }],
    displayRows,
    filtered.length === 0
      ? `No sampled BOM item shows a real ${isMissing ? 'missing component/quantity' : 'non-blank DiscontinuationGroup'} in this landscape's live data \u2014 honest zero-result, not fabricated.`
      : `Real live DiscontinuationGroup / component fields from BILLOFMATERIALV2_SRV/C_BillOfMaterialItemTP.`
  );
}

