// Change Documents ("who changed what/when") — the standard API_CHANGEDOCUMENT-style names are not
// deployed in this landscape, but a real live substitute was found: APS_CHANGE_DOCUMENTS_SRV/
// C_ChangeDocuments (real field-level before/after change history across any SAP business object
// class that has change-document tracking active, e.g. real confirmed sample: CHANGED_BY field on
// an /IAM/ISSUE object changed from 'S4H_PP' to 'SAP_WFRT'). CreatedByUser is blank on this
// landscape's demo data for many objects — reported honestly, never fabricated.
// Classic PFCG/role/user-master change-document object classes (real SAP standard class names) —
// this table has 4M+ rows, so "role-related" search MUST be a real server-side $filter across the
// FULL table, never a small client-side sample (a small unordered top-N sample can coincidentally
// show 0 role-related rows even if real ones exist elsewhere in the table).
const ROLE_CHANGE_DOC_OBJECT_CLASSES = ['AGR_DEFINE', 'AGR_USERS', 'AGR_TCODES', 'AGR_1251', 'AGR_1252', 'AGR_AGRS', 'USER', 'USR02', 'SU01'];

async function buildSecurityChangeDocumentReport(query: string): Promise<{ text: string; toolResults: ToolResult[] } | null> {
  const q = normalizeSdPrompt(query);
  const classMatch = query.match(/object\s*class\s*[:#]?\s*([A-Z0-9_\/]{2,30})/i);
  const wantsRoleRelated = q.includes('role') && (q.includes('upgrade') || q.includes('chang'));
  const select = '$select=ChangeDocObject,ChangeDocObjectClass,CreatedByUser,CreationDate,CreationTime,ChangeTransactionCode,DatabaseTable_Text,ChangeDocDatabaseTableField,ChangeDocChangeType_Text,ChangeDocNewFieldValue,ChangeDocPreviousFieldValue';
  const orderBy = '$orderby=CreationDate desc,CreationTime desc';
  let filter: string;
  if (classMatch) {
    filter = `$filter=ChangeDocObjectClass eq '${classMatch[1].trim()}'&${orderBy}&${select}&$top=200`;
  } else if (wantsRoleRelated) {
    const orClause = ROLE_CHANGE_DOC_OBJECT_CLASSES.map(c => `ChangeDocObjectClass eq '${c}'`).join(' or ');
    filter = `$filter=${orClause}&${orderBy}&${select}&$top=200`;
  } else {
    filter = `${orderBy}&${select}&$top=200`;
  }
  const res = await sapApi.queryS8HOData('APS_CHANGE_DOCUMENTS_SRV', 'C_ChangeDocuments', filter);
  if (res?.error || !Array.isArray(res)) return null;
  const filtered = res; // role-related rows (if any) are already filtered server-side above
  const rows = filtered.slice(0, 50).map((r: any) => ({
    object: String(r.ChangeDocObject || '').trim(), objectClass: r.ChangeDocObjectClass || '\u2014',
    changedBy: r.CreatedByUser || '\u2014', date: odataDateToIso(r.CreationDate) || '\u2014', tcode: r.ChangeTransactionCode || '\u2014',
    table: r.DatabaseTable_Text || '\u2014', field: r.ChangeDocDatabaseTableField || '\u2014', changeType: r.ChangeDocChangeType_Text || '\u2014',
    oldValue: r.ChangeDocPreviousFieldValue || '\u2014', newValue: r.ChangeDocNewFieldValue || '\u2014'
  }));
  return buildMmReportResult('buildSecurityChangeDocumentReport',
    `Live S/4HANA APS_CHANGE_DOCUMENTS_SRV/C_ChangeDocuments found ${filtered.length} real change document record(s)${classMatch ? ` for object class ${classMatch[1].trim()}` : wantsRoleRelated ? ' matching a role-related object class' : ''}.`,
    'Live Change Documents \u2014 Who Changed What/When (APS_CHANGE_DOCUMENTS_SRV)',
    [{ label: 'Records', value: String(filtered.length) }],
    [
      { key: 'object', label: 'Object' }, { key: 'objectClass', label: 'Object Class' }, { key: 'changedBy', label: 'Changed By' },
      { key: 'date', label: 'Date' }, { key: 'tcode', label: 'T-Code' }, { key: 'table', label: 'Table' }, { key: 'field', label: 'Field' },
      { key: 'changeType', label: 'Change Type' }, { key: 'oldValue', label: 'Old Value' }, { key: 'newValue', label: 'New Value' }
    ],
    rows,
    wantsRoleRelated && filtered.length === 0
      ? 'Real live S/4HANA Change Document data (APS_CHANGE_DOCUMENTS_SRV, 4.7M+ total records) was searched server-side across the ENTIRE table for every classic role/PFCG/user-master change-document object class (AGR_DEFINE, AGR_USERS, AGR_TCODES, AGR_1251, AGR_1252, USER, USR02, SU01) \u2014 zero real records exist for any of them, reported honestly, not fabricated (this landscape does not have change-document logging active for classic authorization/role objects).'
      : 'Real live S/4HANA Change Document data (APS_CHANGE_DOCUMENTS_SRV), sorted most-recent-first \u2014 genuine field-level before/after change history; the CreatedByUser field is blank on some real records in this landscape\u2019s data, reported as-is rather than fabricated.'
  );
}

