//    never fabricated).
const TM_FRT_ORD_ACCR_BASE = '/sap/opu/odata/sap/UI_FREIGHTORDER_ACCR';
const TM_CARRIER_ACCESS_BASE = '/sap/opu/odata/scwm/DAS_CARRIER_ACCESS_SRV';
const TM_FREIGHT_RFQ_BASE = '/sap/opu/odata/sap/UI_COLLABNAPPLFREIGHTRFQ';

// Thin wrapper reusing the same raw-fetch primitive as the BW engine, since this is also
// classic OData V2 (not the srvd_a2x V4 shape EWM uses).
async function queryTmV2(basePath: string, entity: string, query: string): Promise<any[] | null> {
  const res = await queryBwV2Raw(`${basePath}/${entity}?${query}`);
  if (!res.ok) return null;
  return Array.isArray(res.json?.d?.results) ? res.json.d.results : null;
}

// Real live Freight/Transportation Charge Elements (settlement-level charge line items) — the
// genuine live substitute for "Freight Settlement" in this landscape.
async function buildTmFreightChargeReport(query: string): Promise<{ text: string; toolResults: ToolResult[] } | null> {
  const q = normalizeSdPrompt(query);
  const rows = await queryTmV2(TM_FRT_ORD_ACCR_BASE, 'C_FrtOrdAccrChrgElmnt', `$select=TranspChargeItemElementUUID,TranspChargeType,TranspChargeTypeDesc,TranspChargeDocumentCurrency,TranspChrgAmountInDocCurrency,TranspChrgDataSourceQuantity,TranspChrgCalcRuleUnit&$top=500&$format=json`);
  if (!rows) return null;

  if (q.includes('by charge type') || q.includes('by type') || (q.includes('total') && !q.includes('detail'))) {
    const byType = new Map<string, { total: number; currency: string; count: number }>();
    for (const r of rows) {
      const type = String(r.TranspChargeType || 'Unassigned');
      const amt = Number(r.TranspChrgAmountInDocCurrency) || 0;
      const entry = byType.get(type) || { total: 0, currency: r.TranspChargeDocumentCurrency || '', count: 0 };
      entry.total += amt; entry.count += 1;
      byType.set(type, entry);
    }
    const typeRows = Array.from(byType.entries()).map(([chargeType, v]) => ({ chargeType, totalAmount: Math.round(v.total * 100) / 100, currency: v.currency, lineItems: v.count })).sort((a, b) => b.totalAmount - a.totalAmount);
    return buildMmReportResult('queryTmV2',
      `Live S/4HANA UI_FREIGHTORDER_ACCR/C_FrtOrdAccrChrgElmnt aggregated ${rows.length} real live transportation charge element(s) across ${typeRows.length} charge type(s).`,
      'Live Freight/Transportation Charges by Type (UI_FREIGHTORDER_ACCR)',
      [{ label: 'Charge Elements Sampled', value: String(rows.length) }, { label: 'Charge Types', value: String(typeRows.length) }],
      [{ key: 'chargeType', label: 'Charge Type' }, { key: 'totalAmount', label: 'Total Amount' }, { key: 'currency', label: 'Currency' }, { key: 'lineItems', label: '# Line Items' }],
      typeRows,
      'Real live TranspChargeType/TranspChrgAmountInDocCurrency from C_FrtOrdAccrChrgElmnt — this landscape\'s genuine live substitute for "Freight Settlement" data (the dedicated API_FREIGHTSETTLEMENT_SRV service itself returns HTTP 403 here). No fabricated charge amounts.'
    );
  }

  const tableRows = rows.slice(0, 50).map((r: any) => ({
    chargeElement: String(r.TranspChargeItemElementUUID || '').slice(0, 8),
    chargeType: r.TranspChargeType || '—',
    amount: r.TranspChrgAmountInDocCurrency,
    currency: r.TranspChargeDocumentCurrency || '—',
    quantity: r.TranspChrgDataSourceQuantity,
    unit: r.TranspChrgCalcRuleUnit || '—'
  }));
  return buildMmReportResult('queryTmV2',
    `Live S/4HANA UI_FREIGHTORDER_ACCR/C_FrtOrdAccrChrgElmnt sampled ${rows.length} real live transportation charge element(s).`,
    'Live Freight/Transportation Charge Elements (UI_FREIGHTORDER_ACCR)',
    [{ label: 'Charge Elements Sampled', value: String(rows.length) }],
    [{ key: 'chargeElement', label: 'Charge Element' }, { key: 'chargeType', label: 'Charge Type' }, { key: 'amount', label: 'Amount' }, { key: 'currency', label: 'Currency' }, { key: 'quantity', label: 'Calc Quantity' }, { key: 'unit', label: 'Calc Unit' }],
    tableRows,
    'Real live transportation/freight charge line items from C_FrtOrdAccrChrgElmnt (real amounts/currency/charge type) — this landscape\'s genuine live substitute for "Freight Settlement" data, no fabricated charges.'
  );
}

