    // scoping) — checked BEFORE the generic isJournalEntryIntent below so these get an honest,
    // specific disclosure instead of a misleading unfiltered full-listing implying they were
    // actually filtered.
    const glSpecificGapReason = backendTarget !== 'ECC' && !images?.length ? ((): string | null => {
      const n = normalizedForReport;
      if ((n.includes('journal entr') || n.includes('financial posting')) && n.includes('require') && n.includes('approv')) {
        return 'Live S/4HANA API_JOURNALENTRYITEMBASIC_SRV only exposes already-POSTED Universal Journal line items — there is no live parked-document/workflow-approval status field on this API (a parked/pending-approval document is a different data source), so "requiring approval" cannot be determined live.';
      }
      if (n.includes('recurring') && n.includes('journal')) {
        return 'No live recurring-entry schedule field (comparable to classic FBD1/F.14 recurring document data) is exposed by API_JOURNALENTRYITEMBASIC_SRV in this landscape, so scheduled/recurring journal entries cannot be identified live.';
      }
      if (n.includes('unbalanced') && n.includes('journal')) {
        return 'A document-level debit/credit balance check requires the real Accounting Document number, which is not exposed as a field on API_JOURNALENTRYITEMBASIC_SRV in this landscape (confirmed HTTP 404) — line items cannot be grouped into documents to verify balance live.';
      }
      if ((n.includes('journal entr') || n.includes('financial posting')) && n.includes('today')) {
        return 'No live PostingDate field is exposed by API_JOURNALENTRYITEMBASIC_SRV in this landscape (confirmed HTTP 404), so postings cannot be scoped to "today" — only an unscoped fiscal-year listing is available live.';
      }
      return null;
    })() : null;
